CREATE TABLE IF NOT EXISTS "site_model_aliases" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "site_id" INTEGER NOT NULL, "source_model" TEXT NOT NULL, "alias_model" TEXT NOT NULL, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("site_id") REFERENCES "sites"("id") ON DELETE CASCADE);
ALTER TABLE "downstream_api_keys" ADD COLUMN "auto_sync_routes" INTEGER DEFAULT 0;
ALTER TABLE "sites" ADD COLUMN "client_spoofing" TEXT DEFAULT 'none';
CREATE UNIQUE INDEX "site_model_aliases_site_alias_unique" ON "site_model_aliases" ("site_id", "alias_model");
CREATE UNIQUE INDEX "site_model_aliases_site_source_alias_unique" ON "site_model_aliases" ("site_id", "source_model", "alias_model");
CREATE INDEX "site_model_aliases_alias_model_idx" ON "site_model_aliases" ("alias_model");
CREATE INDEX "site_model_aliases_site_id_idx" ON "site_model_aliases" ("site_id");
